                                                "script": {
                                                    "apiVersion": "1.0.0",
                                                    "inlineScript": "/**\n  * @param {params} params\n  * @param {api} params.api\n  * @param {any} params.imports\n  */\nfunction evaluateProperty({api}) {\n  if(api.data.get_data_related_to_citation_sidebar.output.hideHierarchyNone){\n    return false;\n  }\n\treturn true;\n}"
