                                                "expandedItems": {
                                                    "script": {
                                                        "apiVersion": "2.0.0",
                                                        "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n\n    var expandedItems = api.data.get_data_related_to_citation_sidebar.output.hierarchy.expandedItems;\n\n    for (var i = 0; i < expandedItems.length; i++) {\n      expandedItems[i].unshift(api.data.get_data_related_to_citation_sidebar.output.adSysId);\n    }\n\n    return api.data.get_data_related_to_citation_sidebar.output.expandedItems;\n}"
                                                    },
                                                    "type": "CLIENT_TRANSFORM_SCRIPT"
                                                },
                                                "highlightSelectedParent": {
                                                    "type": "JSON_LITERAL",
                                                    "value": false
                                                },
                                                "items": {
                                                    "script": {
                                                        "apiVersion": "2.0.0",
                                                        "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n\n    if (api.data.get_data_related_to_citation_sidebar.output) {\n        var transformItems = api.data.get_data_related_to_citation_sidebar.output.hierarchy.items;\n        if (api.data.get_data_related_to_citation_sidebar.output.adSysId) {\n\n            var authorityDocumentItems = [{\n                \"actionable\": true,\n                \"children\": transformItems,\n                \"highlightedValueProps\": [],\n                \"table\": \"sn_compliance_authority_document\",\n                \"identifierProps\": {\n                    \"icon\": \"document-outline\"\n                },\n                \"id\": api.data.get_data_related_to_citation_sidebar.output.adSysId,\n                \"label\": api.data.get_data_related_to_citation_sidebar.output.adName\n            }];\n            return authorityDocumentItems;\n        } else return transformItems;\n    }\n}"
                                                    },
                                                    "type": "CLIENT_TRANSFORM_SCRIPT"
                                                },
